"""Walks .github through a def that returns its own directory: no name is
bound to __file__'s directory, so only a traced run shows the walk."""
import os


def here():
    return os.path.dirname(os.path.abspath(__file__))


def sweep():
    top = os.path.dirname(here())
    return [f for _r, _d, files in os.walk(top) for f in files]


sweep()
print("ok")

